package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

// 01 SALES-REC, 12 bytes
type SalesRec struct {
	SrId    string          // PIC X(4) @0 len=4
	SrSales decimal.Decimal // PIC 9(6)V99 @4 len=8
}

type TierEntry struct {
	TierLimit decimal.Decimal // PIC 9(6)V99 len=8
	TierRate  decimal.Decimal // PIC 9V99 len=3
}

// Working-storage
var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.New(0, 0)
var WsTotal decimal.Decimal = decimal.New(0, 0)
var WsCount int64 = 0
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

var tierEntries [4]TierEntry

var salesRec SalesRec

// file reading state
var inputLines []string
var inputPos int = 0

func isInputDone() bool { return WsEofFlag == "Y" }

func initPara() {
	tierEntries[0].TierLimit = decimal.NewFromFloat(1000.00)
	tierEntries[0].TierRate = decimal.RequireFromString("2.50")
	tierEntries[1].TierLimit = decimal.NewFromFloat(5000.00)
	tierEntries[1].TierRate = decimal.RequireFromString("4.00")
	tierEntries[2].TierLimit = decimal.NewFromFloat(20000.00)
	tierEntries[2].TierRate = decimal.RequireFromString("5.50")
	tierEntries[3].TierLimit = decimal.RequireFromString("999999.99")
	tierEntries[3].TierRate = decimal.RequireFromString("7.25")
	// Ensure scales correct: TierLimit scale 2, TierRate scale 2
	// Force scale 2 by rounding
	for i := 0; i < 4; i++ {
		tierEntries[i].TierLimit = tierEntries[i].TierLimit.Round(2)
		tierEntries[i].TierRate = tierEntries[i].TierRate.Round(2)
	}
}

func readPara() {
	if inputPos >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputPos]
	inputPos++
	// pad to 12 with spaces on right
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	// parse SR-ID 0:4
	srId := line[0:4]
	// parse SR-SALES 4:12 8 bytes
	rawSales := line[4:12]
	srSales := parseP9V99(rawSales, 2)
	salesRec.SrId = srId
	salesRec.SrSales = srSales
}

func parseP9V99(s string, scale int32) decimal.Decimal {
	// DISPLAY numeric field stores digits only, implied decimal
	// s is len = digits
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return decimal.New(0, 0)
	}
	// keep only digits (and possibly sign? not needed)
	// remove spaces
	trimmed = strings.ReplaceAll(trimmed, " ", "")
	if trimmed == "" {
		return decimal.New(0, 0)
	}
	// It may contain only digits; if it contains '.' (should not), handle
	// Parse as integer
	d := decimal.RequireFromString(trimmed)
	// shift implied decimal
	return decimal.New(d.IntPart(), -scale)
}

// storeNumeric simulates moving value into PIC 9(intDigits)V99 etc keeping low-order digits
func storeNumeric(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// round/truncate already done outside; here handle overflow
	// keep scale digits
	// For negative values handle sign separately
	sign := val.Sign()
	if sign < 0 {
		val = val.Neg()
	}
	//Separate integer and fractional
	// Get integer part
	intPart := val.IntPart() // truncated toward zero for positive; note IntPart discards fractional
	// fractional part = val - intPart
	frac := val.Sub(decimal.New(intPart, 0))
	// compute modulus for intPart
	if intDigits < 19 {
		mod := int64(1)
		for i := 0; i < intDigits; i++ {
			mod *= 10
		}
		// if intPart >= mod, keep low-order
		if intPart >= mod || intPart <= -mod {
			intPart = intPart % mod
			if intPart < 0 {
				intPart = -intPart
			}
		}
	} else {
		// use decimal modulus for larger
		modDec := decimal.New(1, int32(intDigits)) // 10^intDigits
		intDec := decimal.New(intPart, 0)
		if intDec.GreaterThanOrEqual(modDec) {
			intDec = intDec.Mod(modDec)
			intPart = intDec.IntPart()
		}
	}
	res := decimal.New(intPart, 0).Add(frac)
	if sign < 0 {
		res = res.Neg()
	}
	// ensure scale
	// The value already has scale, but we force truncate/pad to scale
	// Use Truncate then ensure trailing zeros preserved via res (decimal keeps trailing?)
	// For storage, we want exactly scale fractional digits, but decimal equality fine.
	return res
}

func formatPic9(val int64, width int) string {
	s := fmt.Sprintf("%d", val)
	if len(s) > width {
		// keep low-order digits
		s = s[len(s)-width:]
	} else if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	}
	return s
}

func formatEdited(pic string, val decimal.Decimal) string {
	// pic like "ZZZ,ZZ9.99" or "9.99" etc. length = output width.
	// Determine integer part pic and fractional part pic
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	fracPlaceholders := 0
	for _, ch := range fracPic {
		if ch == 'Z' || ch == '9' {
			fracPlaceholders++
		}
	}
	intPlaceholders := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intPlaceholders++
		}
	}
	// Ensure val is rounded/truncated appropriately? For MOVE, assume val already correct scale.
	// But to get integer/fractional digits we need to separate.
	// Work with absolute value (no sign handling needed for this program)
	neg := val.Sign() < 0
	if neg {
		val = val.Neg()
	}
	// Round fractional to required placeholders if needed? For display, we should truncate? Actually MOVE truncates, but values already at scale 2.
	// We'll truncate to fracPlaceholders to avoid rounding issues.
	// Use Truncate to get fractional representation consistent.
	// To extract digits, we can format val with exactly fracPlaceholders decimals via StringFixed-like
	// Use val.StringFixed? but use decimal operations.
	// Get integer part as int
	// We need integer part low-order truncation
	intPartDec := val.Truncate(0) // integer part
	// Actually val may have fraction; intPart = floor for positive
	intPartInt := intPartDec.IntPart()
	// modulus for overflow
	if intPlaceholders > 0 {
		// keep low-order intPlaceholders digits
		mod := int64(1)
		// compute 10^intPlaceholders as int64 if fits (max 9 => fits)
		overflow := false
		var modDec decimal.Decimal
		if intPlaceholders <= 18 {
			m := int64(1)
			for i := 0; i < intPlaceholders; i++ {
				m *= 10
			}
			if intPartInt >= m {
				intPartInt = intPartInt % m
				overflow = true
			}
			_ = overflow
			_ = mod
		} else {
			modDec = decimal.New(1, int32(intPlaceholders))
			if decimal.New(intPartInt, 0).GreaterThanOrEqual(modDec) {
				intPartInt = decimal.New(intPartInt, 0).Mod(modDec).IntPart()
			}
		}
	}
	// Build integer digits padded to intPlaceholders
	intDigitsStr := fmt.Sprintf("%d", intPartInt)
	// if intDigitsStr longer than placeholders (should not after mod) truncate high order
	if len(intDigitsStr) > intPlaceholders {
		intDigitsStr = intDigitsStr[len(intDigitsStr)-intPlaceholders:]
	}
	paddedIntDigits := strings.Repeat("0", intPlaceholders-len(intDigitsStr)) + intDigitsStr
	// If intPlaceholders ==0 (unlikely) padded empty
	// Now build integer section output
	outInt := make([]rune, len(intPic))
	placeholderIdx := 0
	// First fill digits into placeholder positions mapping left-to-right using paddedIntDigits
	// Create array of digits for each placeholder position in order
	// We already have paddedIntDigits length == intPlaceholders
	// Walk intPic left to right, assign
	// But we need to know suppressed state
	// Prepare digitForPlaceholder aligned
	// Instead, walk and assign
	suppressed := true
	// Need placeholderIdx to index paddedIntDigits
	placeholderIdx = 0
	for i, ch := range intPic {
		if ch == ',' {
			// will decide later based on suppressed
			// temporarily store ','
			outInt[i] = ','
		} else if ch == 'Z' || ch == '9' {
			digitChar := rune(paddedIntDigits[placeholderIdx])
			placeholderIdx++
			if suppressed {
				if ch == '9' {
					outInt[i] = digitChar
					suppressed = false
				} else { // Z
					if digitChar == '0' {
						// check if this is the last integer placeholder and all remaining are zero? Actually Z should still be space unless non-zero encountered.
						// For Z, leading zero => space
						outInt[i] = ' '
					} else {
						outInt[i] = digitChar
						suppressed = false
					}
				}
			} else {
				outInt[i] = digitChar
			}
		} else {
			outInt[i] = ch
		}
	}
	// Second pass to turn commas in suppressed region to spaces
	// Our loop already suppressed? But commas before suppressed end should be spaces.
	// We need to know per comma whether suppressed still true at that point.
	// The above loop kept suppressed flag updated only at placeholders, but commas between placeholders should reflect suppressed state at that point.
	// Our outInt for commas was set to ',' regardless of suppressed. Fix:
	suppressed = true
	placeholderIdx = 0
	// Need to simulate again to set commas correctly: we can recompute suppressed per position
	// Do a pass that tracks suppressed up to each position
	suppressed = true
	// We need to know digit for each placeholder to decide transition, but we have paddedIntDigits
	// Iterate left to right again to set commas
	pIdx := 0
	for i, ch := range intPic {
		if ch == ',' {
			if suppressed {
				outInt[i] = ' '
			} else {
				outInt[i] = ','
			}
		} else if ch == 'Z' || ch == '9' {
			digitChar := rune(paddedIntDigits[pIdx])
			pIdx++
			if suppressed {
				if ch == '9' {
					suppressed = false
				} else {
					if digitChar != '0' {
						suppressed = false
					}
				}
			}
			// outInt already set
		}
	}
	intSection := string(outInt)

	// Fractional part
	fracSection := ""
	if fracPlaceholders > 0 {
		// get fractional digits rounded/truncated to fracPlaceholders
		// Extract fraction: val - intPartDec (but intPartDec is truncated integer, for positive it's integer part)
		// Use val to get fractional string with required scale
		// Method: get val scaled to integer of fracPlaceholders: (val - intPart) * 10^fracPlaceholders truncated
		fracDec := val.Sub(decimal.New(intPartInt, 0))
		// shift
		shifted := fracDec.Shift(int32(fracPlaceholders)) // *10^n
		// truncate toward zero
		shifted = shifted.Truncate(0)
		fracInt := shifted.IntPart()
		if fracInt < 0 {
			fracInt = -fracInt
		}
		fracStr := fmt.Sprintf("%0*d", fracPlaceholders, fracInt)
		if len(fracStr) > fracPlaceholders {
			fracStr = fracStr[len(fracStr)-fracPlaceholders:]
		}
		fracSection = fracStr
		if dotIdx >= 0 {
			return intSection + "." + fracSection
		}
		return intSection + fracSection
	}
	if dotIdx >= 0 {
		return intSection + "."
	}
	return intSection
}

func processPara() {
	WsTier = 0
	for wsIdx := int64(1); wsIdx <= 4; wsIdx++ {
		if WsTier > 0 {
			break
		}
		// WS-IDX in COBOL loop variable; use wsIdx
		if salesRec.SrSales.Cmp(tierEntries[wsIdx-1].TierLimit) <= 0 {
			WsTier = wsIdx
		}
	}
	// COMPUTE WS-COMM ROUNDED = SR-SALES * TIER-RATE(WS-TIER) /100
	rate := tierEntries[WsTier-1].TierRate
	comp := salesRec.SrSales.Mul(rate).Shift(-2) // divide by 100
	compRounded := comp.Round(2)
	WsComm = storeNumeric(compRounded, 6, 2)
	// ADD WS-COMM TO WS-TOTAL
	WsTotal = WsTotal.Add(WsComm)
	WsTotal = storeNumeric(WsTotal, 9, 2)
	WsCount++

	WsSalesEd = formatEdited("ZZZ,ZZ9.99", salesRec.SrSales)
	WsRateEd = formatEdited("9.99", rate)
	WsCommEd = formatEdited("ZZZ,ZZ9.99", WsComm)

	// DISPLAY SR-ID " T" WS-TIER " " WS-SALES-ED " " WS-RATE-ED "% " WS-COMM-ED
	tierStr := formatPic9(WsTier, 1)
	line := salesRec.SrId + " T" + tierStr + " " + WsSalesEd + " " + WsRateEd + "% " + WsCommEd
	fmt.Fprintln(os.Stdout, line)

	readPara()
}

func summaryPara() {
	WsTotalEd = formatEdited("ZZZ,ZZZ,ZZ9.99", WsTotal)
	countStr := formatPic9(WsCount, 3)
	line := "REPS: " + countStr + " TOTAL: " + WsTotalEd
	fmt.Fprintln(os.Stdout, line)
}

func main() {
	initPara()

	// Open input.dat
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// Increase buffer if needed
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 10*1024*1024)
	// Use ScanLines (default) - need to allow reading lines with spaces
	// Keep lines as returned (without newline)
	var lines []string
	for scanner.Scan() {
		txt := scanner.Text()
		lines = append(lines, txt)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	inputLines = lines
	inputPos = 0

	// OPEN INPUT SALES-FILE ; PERFORM READ-PARA
	readPara()
	for !isInputDone() {
		processPara()
	}
	summaryPara()
}
